achados.correcao_recomendada:
Validar no cliente (antes de enviar) com Zod, incluindo o tamanho real do base64 decodificado e o prefixo de magic bytes mais comuns; e reforçar no servidor com `[MaxLength]` + verificação de assinatura binária.

```ts
import { z } from 'zod';

const MAX_FOTO_BYTES = 4 * 1024 * 1024; // 4MB por foto, já compactada a quality:0.7

function tamanhoBase64EmBytes(base64: string): number {
  return Math.ceil((base64.length * 3) / 4);
}

function temAssinaturaDeImagemValida(base64: string): boolean {
  const header = Buffer.from(base64.slice(0, 12), 'base64').toString('hex');
  return header.startsWith('ffd8ff') || header.startsWith('89504e47'); // JPEG ou PNG
}

const fotoSchema = z.string().refine(
  (b64) => tamanhoBase64EmBytes(b64) <= MAX_FOTO_BYTES,
  { message: 'Foto excede o tamanho máximo de 4MB.' }
).refine(temAssinaturaDeImagemValida, {
  message: 'Arquivo não reconhecido como imagem JPEG/PNG válida.',
});

fotoSchema.parse(asset.base64); // lança ZodError se inválido — bloqueia antes do envio
```
